 * Parses a limiter file into declarations and events. Throws {@link
 * ParseError} on the first invalid line, matching the specification's
 * "stop at the first one" rule.
 */
import { ParseError } from './errors.js'

const TOKEN_RE = /^[A-Za-z0-9_.\/:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

function fail(line, reason) {
  throw new ParseError(line, reason)
}

function parseUint(str, field, least, line) {
  if (UINT_RE.test(str)) {
    const value = BigInt(str)
    if (value >= least) return value
  }
  fail(line, `${field} must be an integer of at least ${least}`)
}

/**
 * @param {string} text the raw limiter file, as read from standard input
 * @returns {{policies: Map<string, object>, routes: Array<object>, events: Array<object>}}
 */
export function parseLog(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < rawLines.length; i++) {
    const line = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const parts = trimmed.split(/\s+/)
    const directive = parts[0]
    const args = parts.slice(1)

    if (directive === 'bucket') {
      if (args.length !== 4) fail(line, 'expected bucket <name> <capacity> <refill> <per>')
      if (seenEvent) fail(line, 'declarations must come before the first event')
      const [name, capacityStr, refillStr, perStr] = args
      if (!TOKEN_RE.test(name)) fail(line, `invalid policy name ${name}`)
      if (policies.has(name)) fail(line, `policy ${name} is declared twice`)
      const capacity = parseUint(capacityStr, 'capacity', 1n, line)
      const refill = parseUint(refillStr, 'refill', 0n, line)
      const per = parseUint(perStr, 'per', 1n, line)
      policies.set(name, { kind: 'bucket', name, capacity, refill, per })
    } else if (directive === 'window') {
      if (args.length !== 3) fail(line, 'expected window <name> <limit> <span>')
      if (seenEvent) fail(line, 'declarations must come before the first event')
      const [name, limitStr, spanStr] = args
      if (!TOKEN_RE.test(name)) fail(line, `invalid policy name ${name}`)
      if (policies.has(name)) fail(line, `policy ${name} is declared twice`)
      const limit = parseUint(limitStr, 'limit', 0n, line)
      const span = parseUint(spanStr, 'span', 1n, line)
      policies.set(name, { kind: 'window', name, limit, span })
    } else if (directive === 'route') {
      if (args.length < 2) fail(line, 'expected route <prefix> <policy>...')
      if (seenEvent) fail(line, 'declarations must come before the first event')
      const [prefix, ...policyNames] = args
      if (!TOKEN_RE.test(prefix)) fail(line, `invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) fail(line, `prefix ${prefix} is routed twice`)
      for (const name of policyNames) {
        if (!policies.has(name)) fail(line, `unknown policy ${name}`)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
