    lines.push(`${key} allowed=${totals.allowed} denied=${totals.denied}`)
    totalAllowed += totals.allowed
    totalDenied += totals.denied
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return lines
}

