import { parseLog } from './parse.js'
import { simulate } from './simulate.js'
import { ParseError } from './errors.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatReplay(verdicts) {
  const lines = []
  for (const v of verdicts) {
    lines.push(v.allowed ? `${v.tick} ${v.key} allow` : `${v.tick} ${v.key} deny ${v.deniedBy}`)
  }
  return lines
}

function formatSummary(byKey) {
  const lines = []
  const keys = [...byKey.keys()].sort()
  let totalAllowed = 0
  let totalDenied = 0
  for (const key of keys) {
    const totals = byKey.get(key)
    lines.push(`${key} allowed=${totals.allowed} denied=${totals.denied}`)
    totalAllowed += totals.allowed
    totalDenied += totals.denied
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return lines
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let parsed
  try {
    parsed = parseLog(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: line ${err.line}: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const { verdicts, byKey } = simulate(parsed)
  const lines = mode === 'replay' ? formatReplay(verdicts) : formatSummary(byKey)
  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

